package ghicpp.score

import ghicpp.VirtKind
import ghicpp.hierarchy.ClassHierarchy.MemberKind
import org.junit.jupiter.api.Assertions.assertEquals
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test

class OoResultsTest {
    private val results = """
        % Prolog results autogenerated by OOAnalyzer.
        finalClass(0x401000, 0x405000, 0x8, 0xc, 0x401100, [0x401000, 0x401100, 0x401200]).
        finalClass(0x402000, 0x405020, 0x4, 0x4, 0, [0x402000]).
        finalVFTable(0x405000, 0x8, 0x8, 0x404ff0, 'Derived').
        finalVFTable(0x405020, 0x4, 0x4, 0, '').
        finalVFTableEntry(0x405000, 0, 0x401200).
        finalVFTableEntry(0x405000, 0x4, 0x403000).
        finalInheritance(0x401000, 0x402000, 0, 0x405000, false).
        finalMember(0x401000, 0x4, [0x4, 0x2], certain).
        finalMember(0x402000, 0, [0x4], certain).
        finalMethodProperty(0x401000, constructor, certain).
        finalMethodProperty(0x401100, realDestructor, certain).
        finalMethodProperty(0x401200, virtual, certain).
        finalFileInfo('ABCDEF', 'it''s.exe').
    """.trimIndent()

    @Test
    fun `reads classes, their methods, bases and fields`() {
        val oo = OoResults(results, purecalls = setOf(0x403000L))
        assertEquals("it's.exe", oo.terms.single { it.first == "finalFileInfo" }.second[1])
        val h = oo.snapshot("t").hierarchy
        val derived = h[0x401000]!!
        assertEquals("Derived", derived.qualifiedName)
        assertEquals("00405000", derived.vftable)
        assertTrue(derived.isAbstract)
        assertEquals(0xcL, derived.size)
        val functions = derived.members.filter { it.kind == MemberKind.FUNCTION }
        assertEquals(listOf("Derived", "~Derived", "FUN_00401200"), functions.map { it.name })
        assertEquals(VirtKind.VIRTUAL, functions.last().attrs?.virt)
        assertEquals(listOf("cls_402000" to 0L), derived.bases.map { it.name to it.offset })
        assertEquals("cls_402000", h[0x402000]!!.qualifiedName)
        // Its own field, and its base's vptr in place.
        assertEquals(mapOf(0L to 4, 4L to 4), oo.snapshot("t").fields[0x401000L])
    }
}
